// TH16 v1.00a Extra (stage 7). Source st07.ecl.txt MainSub03:1196-1256,
// dependencies ECir00:6-41 and ECir00_at:43-65.
//
// MainSub03 runs five rotating ECir00 formations from (0,224). Each phase
// spawns one fairy every 2 frames (13 / 13 / 15 / 15 / 20) while stepping the
// shared %F2 direction by -0.349066 rad (phase A/C/E, from 0) or +0.349066 rad
// (phase B/D, from pi); the child inherits that snapshot. Between phases the
// source waits 200 frames.
//
// ECir00 moves along %F2 (speed 0 -> 1 over 60 frames, mode1), waits 60,
// starts ECir00_at, waits 60 more, resets speed to 0 and ramps to 2 over
// 120 frames (mode1), then idles. ECir00_at fires a 4-way ring (type 8 color 2,
// speed 1.5) every 15 frames with base angle = %FINAL_ANGLE (= %F2, since the
// move direction never changes), up to 400 volleys. Fairies stop firing when
// they leave the field, exactly as in the source.

const TIME_LIMIT: int = 1824;
const OPENING_BUFFER: int = 120;

const TH16_RICE: int = 480; // etSprite(0, 8, 2)

// st07.ecl.txt ECir00:6-41
async sub fairy(dir: angle) {
    set_invuln(65535);
    set_hitbox(8fx);   // setHitbox(16,16): first value x0.5
    set_hurtbox(12fx); // setHurtbox(24,24): first value x0.5
    move_vel(0, dir, 0fx, EASE_LINEAR);   // moveVel(%F2, 0.0f)
    move_vel(60, dir, 1fx, EASE_QUAD_IN); // moveVelTime(60, mode1, %F2, 1.0)
    wait(60);
    spawn fairy_fire(dir); // @ECir00_at() async
    wait(60);
    move_vel(0, dir, 0fx, EASE_LINEAR);   // moveVel(%F2, 0.0f)
    move_speed(120, 2fx, EASE_QUAD_IN);   // moveSpeedTime(120, mode1, 2.0)
    loop { wait(1); }
}

// st07.ecl.txt ECir00_at:43-65. The 10deg etAngle spread only offsets extra
// layers, and etCount is 4x1, so the four ways stay at 90deg spacing.
async sub fairy_fire(dir: angle) {
    wait(10);
    for volley in 0..400 { // $B = 400
        for way in 0..4 {
            var a: angle = dir + (way * 16384) as angle;
            // ANIM a=1 birth offset: position -= 4 * velocity (4 x 1.5px).
            _ = fire(TH16_RICE, 2, $self_x - 6fx * cos(a), $self_y - 6fx * sin(a),
                     1.5fx, a, none, none);
        }
        wait(15);
    }
}

// MainSub03_220 / _532 / _924 / _1236 / _1628 loops: one enmCreate every
// 2 frames from (0,224), direction stepping after each spawn.
sub formation(count: int, start: angle, step: angle) {
    var dir: angle = start;
    for i in 0..count {
        _ = spawn_enemy(0fx, 224fx, 120, 0, 0, 0, fairy(dir));
        dir = dir + step;
        wait(2);
    }
}

async sub pattern() {
    wait(OPENING_BUFFER);
    formation(13, 0deg, -20deg);  // MainSub03_364, 13 spawns, %F2 -= 0.349066
    wait(200);
    formation(13, 180deg, 20deg); // MainSub03_676, 13 spawns, %F2 += 0.349066
    wait(200);
    formation(15, 0deg, -20deg);  // MainSub03_1068, 15 spawns
    wait(200);
    formation(15, 180deg, 20deg); // MainSub03_1380, 15 spawns
    wait(200);
    formation(20, 0deg, -20deg);  // MainSub03_1772, 20 spawns
    wait(200);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
